pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 newTimestamp) public {
        newTimestamp = bound(newTimestamp, 1, 10_000_000_000);

        address actor = address(0xBEEF);
        vm.deal(actor, 20 ether);
        vm.deal(address(c), 0);

        vm.warp(1);

        vm.warp(newTimestamp);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");

        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
